function lasSenasteGruppikoner() {
  try {
    const varde = JSON.parse(globalThis.localStorage?.getItem(SENASTE_NYCKEL) ?? "[]");
    return Array.isArray(varde) ? varde.filter((n) => typeof n === "string" && gruppikonNamn(n)).slice(0, MAX_SENASTE) : [];
  } catch {
    return [];
  }
}
