var normalisera = (s) => s.toLocaleLowerCase("sv").trim();
function ord(text) {
  return normalisera(text).split(/[^a-z0-9åäöéü]+/i).filter((o) => o.length > 0);
}
function expandera(o) {
  const ut =   new Map([[o, 1]]);
  for (const [sv, en] of Object.entries(SVENSKA_SYNONYMER)) {
    if (o.startsWith(sv) || o.length >= MIN_ORD && sv.startsWith(o)) en.forEach((e, i) => ut.set(e, Math.max(ut.get(e) ?? 0, i === 0 ? 0.9 : 0.85)));
  }
  return ut;
}
function poang(ikon, sok, ra) {
  const namnDelar = ikon.namn.split("-");
  let basta = ikon.namn === sok || namnDelar[0] === sok ? 100 : ikon.namn.startsWith(sok) ? 60 : 0;
  const sv = (
     
    (GRUPPIKON_SVENSKA[ikon.namn] ?? "").toLocaleLowerCase("sv").split(/\s+/)
  );
  if (sv.includes(sok)) basta = Math.max(basta, 110);
  else if (ra && sok.length >= MIN_ORD && sv.some((o) => o.startsWith(sok))) basta = Math.max(basta, 95);
  for (const tagg of ikon.taggar) {
    const t = tagg.toLowerCase();
    if (t === sok) basta = Math.max(basta, 40);
    else if (t.split(/\s+/).includes(sok)) basta = Math.max(basta, 30);
    else if (ra && sok.length >= 4 && t.startsWith(sok)) basta = Math.max(basta, 10);
  }
  return basta;
}
function sokGruppikoner(fraga, katalog = GRUPPIKONKATALOG) {
  const delar = ord(fraga);
  if (delar.length === 0) return [];
  const traffar = [];
  for (const ikon of katalog) {
    let summa = 0;
    let alla = true;
    for (const d of delar) {
      let b = 0;
      for (const [s, vikt] of expandera(d)) b = Math.max(b, poang(ikon, s, s === d) * vikt);
      if (b === 0) {
        alla = false;
        break;
      }
      summa += b;
    }
    if (alla) traffar.push({ namn: ikon.namn, p: summa });
  }
  return traffar.sort((a, b) => b.p - a.p || a.namn.localeCompare(b.namn)).map((t) => t.namn);
}
function forslagUrGruppnamn(gruppnamn, katalog = GRUPPIKONKATALOG) {
  const delar = ord(gruppnamn).filter((o) => o.length >= MIN_ORD);
  if (delar.length === 0) return [];
  const summa =   new Map();
  for (const d of delar) {
    const sokord = [...expandera(d).keys()];
    for (const ikon of katalog) {
      let b = 0;
      for (const s of sokord) b = Math.max(b, poang(ikon, s, s === d));
      for (const tagg of ikon.taggar) {
        const t = tagg.toLowerCase();
        if (t.length >= MIN_ORD && !t.includes(" ") && d.startsWith(t)) b = Math.max(b, 25);
      }
      if (b > 0) summa.set(ikon.namn, (summa.get(ikon.namn) ?? 0) + b);
    }
  }
  return [...summa.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).map(([n]) => n);
}
